import { useState, useEffect } from "react";
const LOGO = "data:image/png;base64,";


// Toggle: set to true to re-enable the maintenance overlay on production
const MAINTENANCE_ENABLED = true;

export default function MaintenanceOverlay() {
  if (!MAINTENANCE_ENABLED) return null;

  // Skip on dev / IP-based hosts — only show on production domains
  const h = typeof window !== 'undefined' ? window.location.hostname : '';
  if (h === 'localhost' || /^\d+\.\d+\.\d+\.\d+$/.test(h)) return null;

  const [visible, setVisible] = useState(false);
  const [dots, setDots] = useState("");

  useEffect(() => {
    const t = setTimeout(() => setVisible(true), 80);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setDots(d => d.length >= 3 ? "" : d + ".");
    }, 600);
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{
      position: "fixed",
      inset: 0,
      zIndex: 9999,
      background: "rgba(255, 255, 255, 0.55)",
      backdropFilter: "blur(14px) saturate(0.7)",
      WebkitBackdropFilter: "blur(14px) saturate(0.7)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "'IBM Plex Mono', 'Courier New', monospace",
      opacity: visible ? 1 : 0,
      transition: "opacity 0.6s ease",
    }}>

      <div style={{
        position: "relative",
        textAlign: "center",
        padding: "52px 48px",
        maxWidth: 520,
        border: "1px solid rgba(150,100,30,0.3)",
        background: "rgba(255, 252, 245, 0.95)",
        boxShadow: "0 8px 64px rgba(0,0,0,0.15), inset 0 1px 0 rgba(150,100,30,0.15)",
      }}>

        {[
          { top: -1, left: -1, borderTop: "2px solid #8B6210", borderLeft: "2px solid #8B6210" },
          { top: -1, right: -1, borderTop: "2px solid #8B6210", borderRight: "2px solid #8B6210" },
          { bottom: -1, left: -1, borderBottom: "2px solid #8B6210", borderLeft: "2px solid #8B6210" },
          { bottom: -1, right: -1, borderBottom: "2px solid #8B6210", borderRight: "2px solid #8B6210" },
        ].map((s, i) => (
          <div key={i} style={{ position: "absolute", width: 16, height: 16, ...s }} />
        ))}

        <div style={{ marginBottom: 28, display: "flex", justifyContent: "center" }}>
          <img src={LOGO} alt="MCAS" style={{ width: 110, height: "auto", filter: "drop-shadow(0 4px 16px rgba(0,0,0,0.5))" }} />
        </div>

        <div style={{
          width: 48, height: 1,
          background: "linear-gradient(90deg, transparent, #8B6210, transparent)",
          margin: "0 auto 32px",
        }} />

        <p style={{
          fontSize: 14, lineHeight: 1.8,
          color: "rgba(80, 50, 10, 0.9)",
          margin: "0 0 36px", fontWeight: 400,
          letterSpacing: "0.01em", textAlign: "left",
        }}>
          Our server upgrade and migration is complete, but at over half a million evaluations per hour we have a lot to test and verify to ensure everything is working as it should post-migration - hence the somewhat protracted process.
          <br /><br />
          Current subscribers can continue to access MCAS itself via the usual login link.
          <br /><br />
          We expect testing and verification to be complete by 7 April, 23:59 UTC. Thank you for your patience.
        </p>

        <div style={{
          display: "inline-flex", alignItems: "center", gap: 10,
          padding: "8px 20px",
          border: "1px solid rgba(139,98,16,0.3)",
          background: "rgba(139,98,16,0.06)",
        }}>
          <span style={{
            width: 7, height: 7, borderRadius: "50%",
            background: "#8B6210", boxShadow: "0 0 8px #8B6210",
            animation: "pulse 1.8s ease-in-out infinite", display: "inline-block",
          }} />
          <span style={{ fontSize: 10, letterSpacing: "0.25em", color: "rgba(100, 65, 10, 0.75)", textTransform: "uppercase" }}>
            Testing and verification in progress{dots}
          </span>
        </div>

        <style>{`
          @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&display=swap');
          @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
        `}</style>
      </div>
    </div>
  );
}
